  const [candles, setCandles] = useState(true);
  const number = new Intl.NumberFormat(i18n.language, {
    maximumFractionDigits: 2,
  });
  const metrics = [
    ["latest", summary?.latest, "USDT"],
    ["bidDepth", summary?.bidDepth, "BTC"],
    ["askDepth", summary?.askDepth, "BTC"],
